"""Plot fitness over generations for all specified experiments (average and max)"""import jsonimport configimport matplotlib.pyplot as pltimport pandas as pdfrom database_components import Experiment, Generation, Individual, Populationfrom sqlalchemy import selectimport argparsefrom typing import Unionfrom revolve2.experimentation.database import OpenMethod, open_database_sqlite# Manually adjust font size globallyplt.rcParams.update({    "font.size": 10,         # Default text size    "axes.titlesize": 35,    # Title font size    "axes.labelsize": 35,    # Axis label size    "xtick.labelsize": 30,   # Tick label size    "ytick.labelsize": 30,    "legend.fontsize": 30,    "figure.titlesize": 35,    "figure.figsize": (15,12)})def plotFitness(df: pd.DataFrame, figName: str,                 fMin: float, fMax: float) -> None:    """    Plot the mean and max fitnesses of all experiments in a dataframe.    TODO: Add default values    """    agg_per_experiment_per_generation = (        df.groupby(["experiment_id", "generation_index"])        .agg({"fitness": ["max", "mean"]})        .reset_index()    )    agg_per_experiment_per_generation.columns = [        "experiment_id",        "generation_index",        "max_fitness",        "mean_fitness",    ]    agg_per_generation = (        agg_per_experiment_per_generation.groupby("generation_index")        .agg({"max_fitness": ["mean", "std"], "mean_fitness": ["mean", "std"]})        .reset_index()    )    agg_per_generation.columns = [        "generation_index",        "max_fitness_mean",        "max_fitness_std",        "mean_fitness_mean",        "mean_fitness_std",    ]        plt.figure()    # Plot max    plt.plot(        agg_per_generation["generation_index"],        agg_per_generation["max_fitness_mean"],        label="Max fitness",        color="b",        lw=4,    )    plt.fill_between(        agg_per_generation["generation_index"],        agg_per_generation["max_fitness_mean"] - agg_per_generation["max_fitness_std"],        agg_per_generation["max_fitness_mean"] + agg_per_generation["max_fitness_std"],        color="b",        alpha=0.2,    )    # Plot mean    plt.plot(        agg_per_generation["generation_index"],        agg_per_generation["mean_fitness_mean"],        label="Mean fitness",        color="r",        lw=4,    )    plt.fill_between(        agg_per_generation["generation_index"],        agg_per_generation["mean_fitness_mean"]        - agg_per_generation["mean_fitness_std"],        agg_per_generation["mean_fitness_mean"]        + agg_per_generation["mean_fitness_std"],        color="r",        alpha=0.2,    )    title = "Mean and max fitness across repetitions with std as shade"    if figName != None: title += ("\n" + figName)    plt.xlim([0, config.NUM_GENERATIONS_BODY])    plt.ylim([fMin, fMax])    plt.xlabel("Generation index")    plt.ylabel("Fitness (no. of targets reached)")    plt.title(title)    plt.grid(which="major", axis="both")    plt.legend()    plt.show()def plotDelta(dfs: list[pd.DataFrame],               figName: Union[str, None] = None) -> None:    """    Plot the average learning deltas per generation over all experiments.    :param dfs: List of dataframes. First dataframe has to be for warm starting.    """    plt.figure()    colors = ["orange", "darkturquoise"]    labels = ["Warm start", "Cold start"]    for i, df in enumerate(dfs):        agg_exp_gen = (            df.groupby(["experiment_id", "generation_index"])            .agg({"fitness": ["mean"]})            .reset_index()        )        agg_exp_gen.columns = [            "experiment_id",            "generation_index",            "mean_fitness",        ]                # Group and compute deltas + cleanup        agg_exp_gen["delta"] = agg_exp_gen.groupby("experiment_id")["mean_fitness"].diff()        agg_exp_gen = agg_exp_gen.dropna(subset=["delta"])        summary = agg_exp_gen.groupby("generation_index")["delta"].agg(["mean", "std"]).reset_index()                # Plot w/ std shade        plt.plot(            summary["generation_index"],            summary["mean"],            color=colors[i],            label=labels[i],            lw=4)                plt.fill_between(            summary["generation_index"],            summary["mean"] - summary["std"],            summary["mean"] + summary["std"],            color=colors[i], alpha=0.3)                title = f"Average learning delta over generations\n{figName}"        plt.grid(which="major", axis="both")        title = "Learning delta accross repetitions with std as shade\n"    plt.xlim([1, config.NUM_GENERATIONS_BODY])    plt.ylim([0,1])    if figName != None: title += ("\n" + figName)    plt.legend()    plt.title(title)    plt.xlabel("Generation index")    plt.ylabel("Learning delta")    plt.grid(which="major", axis="both")    plt.show()def genDF(fileName):    """    Generates a dataframe for an experiment.    """    dbengine = open_database_sqlite(        fileName, open_method=OpenMethod.OPEN_IF_EXISTS    )    df = pd.read_sql(        select(            Experiment.id.label("experiment_id"),            Generation.generation_index,            Individual.fitness,        )        .join_from(Experiment, Generation, Experiment.id == Generation.experiment_id)        .join_from(Generation, Population, Generation.population_id == Population.id)        .join_from(Population, Individual, Population.id == Individual.population_id),        dbengine,    )        return dfdef main() -> None:    """Run the program."""    # Check for passed arguments    parser = argparse.ArgumentParser(description="Plot the max and mean fitnesses for specified experiments.")    parser.add_argument("-n1", type=str, default=None, help="Specify the name of the first JSON containing databases to combine.")    parser.add_argument("-n2", type=str, default=None, help="Specify the name of the second JSON containing databases to combine.")    parser.add_argument("-nameWarm", type=str, default=None, help="Specify warm start fitness title.")    parser.add_argument("-nameCold", type=str, default=None, help="Specify cold start fitness title.")    parser.add_argument("-fMin", type=float, default=-1.0, help="Minimum fitness in axis. Default: -1")    parser.add_argument("-fMax", type=float, default=2.25, help="Maximum fitness in axis. Default: 2.25")    args = parser.parse_args()        assert args.n1 and args != None, "Specify database names (n1 and n2 flags)."    db_names = [args.n1, args.n2]    databases =[]    for db_n in db_names:        # Import JSON file containing database names        dbList = db_n + ".json"        with open(dbList, 'r') as file:            dbFile = json.load(file)            dbs = dbFile.get("Databases", [])        assert len(dbs) > 0, "Need to import at least 2 databases to combine."                # Read first database in list        data = genDF("Databases/"+dbs[0]+".sqlite")        dbs = dbs[1:]                # Read next databases and combine into one        for fileName in dbs:            df = genDF("Databases/"+fileName+".sqlite")            df.experiment_id += data.experiment_id.max()            data = pd.concat([data, df], ignore_index=True)        print(f"Total of {data.experiment_id.max()} experiments aggregated.")        databases.append(data)            # Generate plots    plotFitness(df=databases[0], figName=args.nameWarm,                 fMin = args.fMin, fMax=args.fMax)    plotFitness(df=databases[1], figName=args.nameCold,                 fMin = args.fMin, fMax=args.fMax)            plotDelta(dfs=databases)if __name__ == "__main__":    main()